const booking=document.querySelector('#booking'),detail=document.querySelector('#detail'),form=document.querySelector('#booking-form');let selected=0;
function openBooking(index){detail.close();if(index!==undefined)form.elements.room.value=rooms[index].name;booking.showModal()}
document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>openBooking());
let photoIndex=0;
const detailPhoto=document.querySelector('#detail-photo');
const photoFrame=document.createElement('div');photoFrame.className='detail-photo-frame';detailPhoto.before(photoFrame);photoFrame.append(detailPhoto);
photoFrame.insertAdjacentHTML('beforeend','<button class="photo-arrow photo-prev" aria-label="Предыдущее фото">←</button><button class="photo-arrow photo-next" aria-label="Следующее фото">→</button><span class="photo-counter" aria-live="polite"></span>');
const thumbnails=document.createElement('div');thumbnails.className='photo-thumbnails';thumbnails.setAttribute('aria-label','Фотографии номера');photoFrame.after(thumbnails);
function showPhoto(index){const r=rooms[selected],photos=r.images||[r.image];photoIndex=(index+photos.length)%photos.length;detailPhoto.src=photos[photoIndex];detailPhoto.alt=r.name+' — фото '+(photoIndex+1);photoFrame.querySelector('.photo-counter').textContent=(photoIndex+1)+' / '+photos.length;thumbnails.querySelectorAll('button').forEach((b,i)=>{b.classList.toggle('active',i===photoIndex);b.setAttribute('aria-pressed',String(i===photoIndex))})}
function openDetail(roomIndex,index=0){selected=roomIndex;const r=rooms[selected];thumbnails.replaceChildren();(r.images||[r.image]).forEach((src,i)=>{const b=document.createElement('button');b.type='button';b.setAttribute('aria-label','Фото '+(i+1)+' — '+r.name);const img=document.createElement('img');img.src=src;img.alt='';img.loading='lazy';b.append(img);b.onclick=()=>showPhoto(i);thumbnails.append(b)});showPhoto(index);document.querySelector('#detail-title').textContent=r.name;document.querySelector('#detail-price').textContent=r.price.toLocaleString('ru-RU')+' ₸ / сутки · '+r.half+' ₸ / полсуток';detail.showModal()}
document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>openDetail(Number(b.dataset.detail)));
photoFrame.querySelector('.photo-prev').onclick=()=>showPhoto(photoIndex-1);photoFrame.querySelector('.photo-next').onclick=()=>showPhoto(photoIndex+1);
detail.addEventListener('keydown',e=>{if(e.target.matches('input,select'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();showPhoto(photoIndex+(e.key==='ArrowRight'?1:-1))}});
let touchStart;detailPhoto.addEventListener('touchstart',e=>{touchStart=e.changedTouches[0].clientX},{passive:true});detailPhoto.addEventListener('touchend',e=>{if(touchStart===undefined)return;let delta=e.changedTouches[0].clientX-touchStart;if(Math.abs(delta)>45)showPhoto(photoIndex+(delta<0?1:-1));touchStart=undefined},{passive:true});
document.querySelectorAll('.room .photo').forEach((b,i)=>{const count=document.createElement('span');count.className='room-photo-count';count.textContent=(rooms[i].images||[rooms[i].image]).length+' фото';b.append(count)});
const gallery=document.querySelector('.gallery');gallery.replaceChildren();rooms.forEach((r,roomIndex)=>(r.images||[r.image]).forEach((src,index)=>{const b=document.createElement('button');b.setAttribute('aria-label','Открыть фото '+(index+1)+': '+r.name);const img=document.createElement('img');img.src=src;img.alt=r.name+' — фото '+(index+1);img.loading='lazy';const caption=document.createElement('span');caption.textContent=r.name+' · '+(index+1)+'/'+r.images.length+' ↗';b.append(img,caption);b.onclick=()=>openDetail(roomIndex,index);gallery.append(b)}));
document.querySelector('#detail-book').onclick=()=>openBooking(selected);
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
const today=new Date();today.setMinutes(today.getMinutes()-today.getTimezoneOffset());const date=today.toISOString().slice(0,10);form.elements.arrival.min=date;form.elements.departure.min=date;
form.elements.arrival.onchange=()=>{let next=new Date(form.elements.arrival.value+'T12:00:00');next.setDate(next.getDate()+1);let min=next.getFullYear()+'-'+String(next.getMonth()+1).padStart(2,'0')+'-'+String(next.getDate()).padStart(2,'0');form.elements.departure.min=min;if(form.elements.departure.value<min)form.elements.departure.value=min};
form.onsubmit=e=>{e.preventDefault();if(form.elements.departure.value<=form.elements.arrival.value){form.elements.departure.setCustomValidity('Выезд должен быть позже заезда');form.elements.departure.reportValidity();return}form.elements.departure.setCustomValidity('');let data=new FormData(form);let message='Здравствуйте! Хочу забронировать номер в Van Gogh.\nНомер: '+data.get('room')+'\nЗаезд: '+data.get('arrival')+'\nВыезд: '+data.get('departure')+'\nИмя: '+data.get('guest')+'\nПодскажите, пожалуйста, наличие и итоговую стоимость.';window.open('https://wa.me/77000254070?text='+encodeURIComponent(message),'_blank','noopener')};
form.elements.departure.oninput=()=>form.elements.departure.setCustomValidity('');
const menu=document.querySelector('.menu-toggle');menu.onclick=()=>{let open=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',open)};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')});
document.querySelector('#next').onclick=()=>document.querySelector('.gallery').scrollBy({left:320,behavior:'smooth'});document.querySelector('#prev').onclick=()=>document.querySelector('.gallery').scrollBy({left:-320,behavior:'smooth'});
